data.script:
function check(v,m){if(!v)throw new Error(m);}
const found=Action.find('QA duplicate café 🐼');
check(found && found.uuid==='BBBF0003-0000-4000-8000-000000000013','first duplicate');
check(Action.find('QA duplicate café 🐼 ')===undefined && Action.find('QA Missing lookup')===undefined,'exact missing names');
const source=Action.find('QA Action lookup link'),url=source.installURL;
check(source.uuid==='BBBF0003-0000-4000-8000-000000000015' && url===source.installURL,'stable source identity/link');
const payload=JSON.parse(decodeURIComponent(url.split('data=')[1]));
check(payload.name===source.name && payload.steps.length===1,'installation payload');
check(Reflect.set(source,'installURL','wrong')===false,'readonly link');
editor.setText('Action lookup link passed café 🐼\n'+url);draft.update();
